import React, { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { Button, Menu, Dropdown, Icon, Row, Col, Input, Alert, Table } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import CampaignStyleWrapper from './campaign.style'
import promoAction from '../../redux/promo/actions'
import moment from 'moment'
import XLSX from 'xlsx'
import downloader from '../../../helpers/downloader'
import { dateGenerator } from '../../../helpers/utility'
import PermissionChecker from '../../../components/permissionChecker'

const SEARCH_STORAGE_KEY = 'campaign_coupon_search'

const { getCouponDetails, getPromoDetails } = promoAction

class CouponTableList extends PureComponent {
  constructor (props) {
    super(props)
    const savedSearch = localStorage.getItem(SEARCH_STORAGE_KEY) || ''
    this.state = {
      dataSource: [],
      filteredData: [],
      searchInput: savedSearch,
      loading: false,
      permissions: [],
      error: false,
      statusAddNewPartner: '',
      dataAddPartner: {},
      pageSize: 10
    }
  }

  getColumns = () => {
    return [
      {
        title: 'ACTION',
        key: 'action',
        width: 130,
        render: (text, record) => (
          <i
            className='fa fa-eye'
            style={{ color: '#424242', fontSize: '18px', cursor: 'pointer' }}
            onClick={() => this.viewCouponDetail(record)}
          />
        )
      },
      {
        title: 'COUPON CODE',
        dataIndex: 'code',
        key: 'code',
        sorter: (a, b) => (a.code || '').localeCompare(b.code || '')
      },
      {
        title: 'START DATE',
        dataIndex: 'start_date',
        key: 'start_date',
        sorter: (a, b) => (a.start_date || '').localeCompare(b.start_date || '')
      },
      {
        title: 'END DATE',
        dataIndex: 'end_date',
        key: 'end_date',
        sorter: (a, b) => (a.end_date || '').localeCompare(b.end_date || '')
      },
      {
        title: 'PROMO',
        dataIndex: 'promotion_name',
        key: 'promotion_name',
        sorter: (a, b) => (a.promotion_name || '').localeCompare(b.promotion_name || '')
      },
      {
        title: 'IS ACTIVE',
        dataIndex: 'is_active',
        key: 'is_active',
        sorter: (a, b) => String(a.is_active).localeCompare(String(b.is_active))
      },
      {
        title: 'Enable via List',
        dataIndex: 'enable_via_list',
        key: 'enable_via_list',
        sorter: (a, b) => String(a.enable_via_list).localeCompare(String(b.enable_via_list))
      },
      {
        title: 'PARTNER',
        dataIndex: 'partner_id',
        key: 'partner_id',
        sorter: (a, b) => (a.partner_id || 0) - (b.partner_id || 0)
      },
      {
        title: 'PRODUCT',
        dataIndex: 'product_id',
        key: 'product_id',
        sorter: (a, b) => (a.product_id || 0) - (b.product_id || 0)
      },
      {
        title: 'AUTO APPLY',
        dataIndex: 'autoapply',
        key: 'autoapply',
        sorter: (a, b) => String(a.autoapply).localeCompare(String(b.autoapply))
      },
      {
        title: 'CREATED',
        dataIndex: 'created_at',
        key: 'created_at',
        render: (text) => text ? moment(text).format('DD MMMM YYYY') : '',
        sorter: (a, b) => moment(a.created_at).unix() - moment(b.created_at).unix()
      },
      {
        title: 'UPDATED',
        dataIndex: 'updated_at',
        key: 'updated_at',
        render: (text) => text ? moment(text).format('DD MMMM YYYY') : '',
        sorter: (a, b) => moment(a.updated_at).unix() - moment(b.updated_at).unix()
      }
    ]
  }

  applySearch = (data, searchValue) => {
    if (!searchValue) return data
    const searchLower = searchValue.toLowerCase()
    return data.filter(record =>
      Object.values(record).some(val =>
        val && val.toString().toLowerCase().includes(searchLower)
      )
    )
  }

  viewCouponDetail = (data) => {
    this.props.history.push(`/campaign/coupon/${data.id}`, { params: { data, createCoupon: false } })
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { couponDetails } = nextProps.promoData
    const data = couponDetails || []
    this.setState({
      dataSource: data,
      filteredData: this.applySearch(data, this.state.searchInput),
      loading: false
    })
  }

  componentDidMount () {
    this.setState({ loading: true })
    this.props.getCouponDetails()
    this.props.getPromoDetails()
  }

  exportToExcel () {
    const { filteredData } = this.state
    const exportData = filteredData.map(row => ({
      'Code': row.code || '',
      'Start Date': row.start_date && row.start_date.Time ? moment(row.start_date.Time).format('YYYY-MM-DD') : '',
      'End Date': row.end_date && row.end_date.Time ? moment(row.end_date.Time).format('YYYY-MM-DD') : '',
      'Promotion ID': row.promotion_id || '',
      'Is Active': row.is_active || '',
      'Enable via List': row.enable_via_list || '',
      'Partner ID': row.partner_id || '',
      'Product ID': row.product_id || '',
      'Auto Apply': row.autoapply || '',
      'Name': row.name || '',
      'Created At': row.created_at ? moment(row.created_at).format('YYYY-MM-DD') : '',
      'Updated At': row.updated_at ? moment(row.updated_at).format('YYYY-MM-DD') : ''
    }))

    const worksheet = XLSX.utils.json_to_sheet(exportData)
    const workbook = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Coupon List')
    const xlsxContent = XLSX.write(workbook, { bookType: 'xlsx', type: 'base64' })
    const params = {
      fileName: 'coupon_list_' + dateGenerator()
    }
    downloader(params, xlsxContent)
  }

  handleClearFilter = () => {
    localStorage.removeItem(SEARCH_STORAGE_KEY)
    this.setState({
      searchInput: '',
      filteredData: this.state.dataSource
    })
  }

  onFilterChange = (val) => {
    const searchValue = val.target.value
    localStorage.setItem(SEARCH_STORAGE_KEY, searchValue)
    this.setState({
      searchInput: searchValue,
      filteredData: this.applySearch(this.state.dataSource, searchValue)
    })
  }

  changePaginationSize = (size) => {
    this.setState({ pageSize: Number(size) })
  }

  handleCreateCoupon = () => {
    this.props.history.push('/campaign/coupon/create-coupon', { params: { createCoupon: true } })
  }

  render () {
    const { filteredData, searchInput, statusAddNewPartner, dataAddPartner, loading, pageSize } = this.state
    const { permissions } = this.props
    const menu = (
      <Menu onClick={this.exportToExcel.bind(this)}>
        <Menu.Item key='1'><Icon type='right-circle-o' /> Excel</Menu.Item>
      </Menu>
    )
    const checkPermissionAddPartner = permissions.filter(value => value === 'ops.create_new_partner')
    const menuPagination = (
      <Menu>
        <Menu.Item key='1' onClick={this.changePaginationSize.bind(this, '50')}>50</Menu.Item>
        <Menu.Item key='2' onClick={this.changePaginationSize.bind(this, '100')}>100</Menu.Item>
        <Menu.Item key='3' onClick={this.changePaginationSize.bind(this, '200')}>200</Menu.Item>
        <Menu.Item key='4' onClick={this.changePaginationSize.bind(this, '300')}>300</Menu.Item>
        <Menu.Item key='5' onClick={this.changePaginationSize.bind(this, '400')}>400</Menu.Item>
        <Menu.Item key='6' onClick={this.changePaginationSize.bind(this, '500')}>500</Menu.Item>
      </Menu>
    )
    return (
      <CampaignStyleWrapper>
        <LayoutContentWrapper className='content-wrapper'>
          {statusAddNewPartner === 'success' && (
            <Row className='error-row'>
              <Col span={24}>
                <Alert
                  className='alert'
                  message={`${dataAddPartner.name} is successful added`}
                  type='success'
                  closeText='Close'
                />
              </Col>
            </Row>
          )}
          {(statusAddNewPartner !== 'success' && statusAddNewPartner !== '') && (
            <Row className='error-row'>
              <Col span={24}>
                <Alert
                  className='alert'
                  message='Failed to add new partner'
                  type='error'
                  closeText='Close'
                />
              </Col>
            </Row>
          )}
          <LayoutContent className='content'>
            <Row gutter={16}>
              <Col className='gutter-row-export-excel' span={24}>
                <h3>Coupon List</h3>
                <div className='btn-container'>
                  {
                    checkPermissionAddPartner.length > 0 && (
                      <Button
                        className='btn-filter'
                        onClick={this.handleCreateCoupon}
                      >
                        <i className='fas fa-plus' /> CREATE COUPON
                      </Button>
                    )
                  }
                  <Button
                    className='btn-filter'
                    onClick={this.handleClearFilter}
                  >
                    <Icon type='filter' /> Clear filters
                  </Button>
                  <Input
                    className='input-filter'
                    value={searchInput}
                    type='text'
                    id='filter-text-box'
                    placeholder='Search...'
                    onInput={val => this.onFilterChange(val)}
                  />
                  <PermissionChecker permissionSetter='ops.downlaod_coupon_list' permissionGetter={permissions}>
                    <Dropdown overlay={menu}>
                      <Button>
                        Export to <Icon type='down' />
                      </Button>
                    </Dropdown>
                  </PermissionChecker>
                  <Dropdown overlay={menuPagination}>
                    <Button className='btn-page-size'>Page size <Icon type='down' /></Button>
                  </Dropdown>
                </div>
              </Col>
            </Row>
            <Table
              columns={this.getColumns()}
              dataSource={filteredData}
              rowKey={(record) => record.id || Math.random()}
              pagination={{
                pageSize: pageSize,
                showSizeChanger: false,
                showQuickJumper: true,
                showTotal: (total, range) => `[${range[0]}-${range[1]}] of ${total} items`
              }}
              scroll={{ x: true, y: true }}
              loading={loading}
              locale={{
                emptyText: 'Data is empty :('
              }}
              style={{ marginTop: '16px' }}
            />
          </LayoutContent>
        </LayoutContentWrapper>
      </CampaignStyleWrapper>
    )
  }
}

CouponTableList.propTypes = {
  partnerData: PropTypes.object.isRequired,
  dataProfile: PropTypes.object.isRequired
}

CouponTableList.defaultProps = {
  partnerData: {},
  dataProfile: {}
}

export default connect(
  state => ({
    promoData: state.PromoDetails,
    dataProfile: state.Auth.profile
  }),
  { getCouponDetails, getPromoDetails }
)(CouponTableList)
